import { useCallback, useEffect, useMemo, useState } from 'react';
import {
  Alert, AppBar, Avatar, Box, Button, Card, CardActionArea, CardContent, Chip, CssBaseline,
  Dialog, DialogActions, DialogContent, DialogTitle, Divider, Drawer, FormControl, FormControlLabel,
  IconButton, InputAdornment, InputLabel, LinearProgress, List, ListItemButton, ListItemIcon,
  ListItemText, MenuItem, Paper, Select, Snackbar, Stack, Switch, Table, TableBody, TableCell,
  TableContainer, TableHead, TableRow, TextField, ThemeProvider, Toolbar, Tooltip, Typography,
  createTheme, useMediaQuery
} from '@mui/material';
import {
  AddRounded, AdminPanelSettingsRounded, AppsRounded, BoltRounded, Brightness4Rounded,
  Brightness7Rounded, ComputerRounded, DashboardRounded, DeleteOutlineRounded, EditRounded,
  HomeRepairServiceRounded, LogoutRounded, MemoryRounded, MenuRounded,
  NetworkCheckRounded, PlayArrowRounded, RefreshRounded, SearchRounded, SecurityRounded,
  SpeedRounded, ThermostatRounded, TimelineRounded, CloseRounded, CameraAltRounded
} from '@mui/icons-material';
import vi from './lang/vi.json';
import en from './lang/en.json';

const DRAWER_WIDTH = 276;
const dictionaries = { vi, en };
const pageMeta = {
  fleet: ['page.fleet.title', 'page.fleet.kicker'], dashboard: ['page.dashboard.title', 'page.dashboard.kicker'],
  processes: ['page.processes.title', 'page.processes.kicker'], watchdog: ['page.watchdog.title', 'page.watchdog.kicker'],
  activity: ['page.activity.title', 'page.activity.kicker'], admin: ['page.admin.title', 'page.admin.kicker']
};

const bytes = value => {
  const input = Number(value || 0); if (!input) return '0 B';
  const units = ['B', 'KB', 'MB', 'GB', 'TB']; const i = Math.min(Math.floor(Math.log(input) / Math.log(1024)), units.length - 1);
  return `${(input / 1024 ** i).toFixed(i > 1 ? 1 : 0)} ${units[i]}`;
};
const percent = value => `${Math.min(100, Math.max(0, Number(value || 0))).toFixed(1)}%`;
const watts = value => Number.isFinite(Number(value)) ? `${Number(value).toFixed(Number(value) >= 100 ? 0 : 1)} W` : '--';
const temperature = value => Number.isFinite(Number(value)) ? `${Number(value).toFixed(1)} °C` : '--';
const uptime = (value, lang) => {
  const seconds = Number(value || 0); const days = Math.floor(seconds / 86400); const hours = Math.floor(seconds % 86400 / 3600); const minutes = Math.floor(seconds % 3600 / 60);
  return lang === 'vi' ? `${days} ngày ${hours} giờ ${minutes} phút` : `${days}d ${hours}h ${minutes}m`;
};
const initials = text => String(text || 'PC').split(/[\s_-]+/).filter(Boolean).slice(0, 2).map(part => part[0]).join('').toUpperCase() || 'PC';

function useTranslation() {
  const [lang, setLangState] = useState(() => localStorage.getItem('wc_lang') || 'vi');
  const setLang = value => { localStorage.setItem('wc_lang', value); setLangState(value); };
  const t = useCallback((key, values = {}) => Object.entries(values)
    .reduce((text, [name, value]) => text.replaceAll(`{${name}}`, String(value)), dictionaries[lang]?.[key] || dictionaries.vi[key] || key), [lang]);
  return { lang, setLang, t };
}

function useApi(token, onExpired) {
  return useCallback(async (url, options = {}) => {
    const headers = { ...(options.headers || {}) };
    if (options.body && !(options.body instanceof FormData)) headers['Content-Type'] = 'application/json';
    if (token) headers.Authorization = `Bearer ${token}`;
    const response = await fetch(url, { ...options, headers });
    const data = await response.json().catch(() => ({}));
    if (response.status === 401) { onExpired(); throw new Error('sessionExpired'); }
    if (!response.ok) throw new Error(data.error || 'generic');
    return data;
  }, [token, onExpired]);
}

const statTones = {
  primary: { gradient: 'linear-gradient(195deg, #5e72e4, #825ee4)', shadow: 'rgba(94,114,228,.35)' },
  secondary: { gradient: 'linear-gradient(195deg, #ec407a, #d81b60)', shadow: 'rgba(216,27,96,.30)' },
  info: { gradient: 'linear-gradient(195deg, #36c5f0, #118ab2)', shadow: 'rgba(17,138,178,.30)' },
  success: { gradient: 'linear-gradient(195deg, #2dce89, #1b9b67)', shadow: 'rgba(27,155,103,.30)' },
  warning: { gradient: 'linear-gradient(195deg, #fb8c00, #f4511e)', shadow: 'rgba(244,81,30,.30)' }
};

function StatCard({ title, value, caption, icon, color = 'primary' }) {
  const tone = statTones[color] || statTones.primary;
  return <Card sx={{ height: '100%', minWidth: 0, overflow: 'visible' }}><CardContent sx={{ p: 2.35, '&:last-child': { pb: 2.35 } }}>
    <Stack direction="row" justifyContent="space-between" alignItems="flex-start" spacing={1.5}><Avatar variant="rounded" sx={{ flexShrink: 0, mt: -.7, width: 52, height: 52, borderRadius: 2.25, color: 'common.white', backgroundImage: tone.gradient, boxShadow: `0 8px 18px ${tone.shadow}` }}>{icon}</Avatar><Box sx={{ minWidth: 0, flex: 1, textAlign: 'right' }}><Typography variant="caption" color="text.secondary" sx={{ fontWeight: 700, letterSpacing: .25, textTransform: 'uppercase' }} noWrap>{title}</Typography><Typography className="metric-value" variant="h4" sx={{ mt: .35, letterSpacing: '-.04em', fontSize: { xs: '1.65rem', sm: '1.9rem' }, lineHeight: 1.15, overflowWrap: 'anywhere' }}>{value}</Typography></Box></Stack>
    {caption && <><Divider sx={{ my: 1.6 }} /><Typography variant="caption" color="text.secondary" sx={{ display: 'block', minHeight: '1.2em', overflowWrap: 'anywhere' }}>{caption}</Typography></>}
  </CardContent></Card>;
}

function StatusChip({ online, label }) { return <Chip size="small" color={online ? 'success' : 'default'} variant={online ? 'filled' : 'outlined'} label={label} sx={{ fontWeight: 700 }} />; }

function LineChart({ values = [], color = '#5e72e4', title, empty }) {
  const points = values.length ? values.map((value, index) => `${(index / Math.max(values.length - 1, 1)) * 100},${100 - Math.max(0, Math.min(100, value))}`).join(' ') : '';
  return <Box><Stack direction="row" alignItems="center" justifyContent="space-between" sx={{ mb: 2 }}><Typography variant="subtitle1">{title}</Typography><Chip size="small" label={values.length ? percent(Math.max(...values)) : '--'} /></Stack>
    {values.length ? <svg className="chart-svg" viewBox="0 0 100 100" preserveAspectRatio="none" role="img" aria-label={title}>
      {[20, 40, 60, 80].map(y => <line key={y} x1="0" x2="100" y1={y} y2={y} stroke="currentColor" opacity=".08" vectorEffect="non-scaling-stroke" />)}
      <defs><linearGradient id={`fill-${color.replace('#', '')}`} x1="0" x2="0" y1="0" y2="1"><stop stopColor={color} stopOpacity=".26"/><stop offset="1" stopColor={color} stopOpacity=".02"/></linearGradient></defs>
      <polygon points={`0,100 ${points} 100,100`} fill={`url(#fill-${color.replace('#', '')})`} /><polyline points={points} fill="none" stroke={color} strokeWidth="2" vectorEffect="non-scaling-stroke" strokeLinecap="round" strokeLinejoin="round" />
    </svg> : <Box sx={{ height: 210, display: 'grid', placeItems: 'center', bgcolor: 'background.neutral', borderRadius: 1.5 }}><Typography color="text.secondary">{empty}</Typography></Box>}
  </Box>;
}

function AuthView({ setup, api, t, onSignedIn }) {
  const [username, setUsername] = useState(''); const [password, setPassword] = useState(''); const [error, setError] = useState(''); const [busy, setBusy] = useState(false);
  const submit = async event => { event.preventDefault(); setBusy(true); setError(''); try {
    if (setup) { await api('/api/setup', { method: 'POST', body: JSON.stringify({ username, password }) }); onSignedIn(null); }
    else { const result = await api('/api/login', { method: 'POST', body: JSON.stringify({ username, password }) }); onSignedIn(result); }
  } catch (err) { setError(t(`error.${err.message}`)); } finally { setBusy(false); } };
  return <Box sx={{ minHeight: '100vh', display: 'grid', placeItems: 'center', p: { xs: 2, sm: 3 }, bgcolor: 'background.default', backgroundImage: 'radial-gradient(circle at 15% 20%, rgba(94,114,228,.14), transparent 30%), radial-gradient(circle at 90% 100%, rgba(17,138,178,.10), transparent 34%)' }}>
    <Paper elevation={0} sx={{ width: 'min(1000px, 100%)', overflow: 'hidden', borderRadius: 4, display: 'grid', gridTemplateColumns: { xs: '1fr', md: '1.08fr .92fr' }, border: 1, borderColor: 'divider', boxShadow: '0 24px 64px rgba(31,38,59,.18)' }}>
      <Box sx={{ color: 'common.white', p: { xs: 4, md: 7 }, minHeight: { md: 550 }, display: 'flex', flexDirection: 'column', justifyContent: 'flex-end', backgroundImage: 'linear-gradient(195deg, #344767 0%, #1d2236 100%), radial-gradient(circle at 82% 15%, rgba(130,94,228,.38), transparent 30%)', position: 'relative', overflow: 'hidden', '&::before': { content: '""', position: 'absolute', inset: 0, opacity: .18, backgroundImage: 'linear-gradient(rgba(255,255,255,.16) 1px, transparent 1px), linear-gradient(90deg, rgba(255,255,255,.16) 1px, transparent 1px)', backgroundSize: '36px 36px', maskImage: 'linear-gradient(to bottom, #000, transparent)' } }}>
        <Avatar variant="rounded" sx={{ position: 'relative', width: 56, height: 56, borderRadius: 2.25, color: 'common.white', fontWeight: 800, backgroundImage: 'linear-gradient(195deg, #5e72e4, #825ee4)', boxShadow: '0 10px 22px rgba(0,0,0,.22)' }}>WC</Avatar><Typography variant="h2" sx={{ position: 'relative', mt: 4, maxWidth: 410 }}>{t('auth.storyTitle')}</Typography><Typography sx={{ position: 'relative', mt: 2, color: 'rgba(255,255,255,.72)', maxWidth: 420 }}>{t('auth.storyDescription')}</Typography>
      </Box>
      <Box component="form" onSubmit={submit} sx={{ p: { xs: 3, sm: 6 }, alignSelf: 'center' }}><Typography variant="h3">{setup ? t('setup.title') : 'Windows Controller Fleet'}</Typography><Typography color="text.secondary" sx={{ mt: 1 }}>{setup ? t('setup.description') : t('login.description')}</Typography>
        <TextField fullWidth required autoComplete="username" label={setup ? t('setup.username') : t('login.username')} value={username} onChange={event => setUsername(event.target.value)} sx={{ mt: 4 }} />
        <TextField fullWidth required type="password" autoComplete={setup ? 'new-password' : 'current-password'} inputProps={{ minLength: setup ? 10 : undefined }} label={setup ? t('setup.password') : t('login.password')} value={password} onChange={event => setPassword(event.target.value)} sx={{ mt: 2 }} />
        {error && <Alert severity="error" sx={{ mt: 2 }}>{error}</Alert>}<Button fullWidth size="large" type="submit" variant="contained" disabled={busy} sx={{ mt: 3 }}>{setup ? t('setup.submit') : t('login.submit')}</Button>
      </Box>
    </Paper>
  </Box>;
}

function FleetPage({ hosts, t, lang, selectHost, openAdmin }) {
  const online = hosts.filter(host => host.online).length; const attention = hosts.filter(host => !host.online || Number(host.telemetry?.cpu?.usage) >= 85 || Number(host.telemetry?.memory?.percent) >= 90).length;
  return <Stack spacing={3}><Stack direction={{ xs: 'column', sm: 'row' }} justifyContent="space-between" alignItems={{ xs: 'flex-start', sm: 'center' }} spacing={2}><Box><Typography variant="h4">{t('fleet.title')}</Typography><Typography color="text.secondary">{t('fleet.description')}</Typography></Box>{openAdmin && <Button onClick={openAdmin} variant="contained" startIcon={<AddRounded />}>{t('fleet.approve')}</Button>}</Stack>
    <Box sx={{ display: 'grid', gridTemplateColumns: { xs: '1fr', sm: 'repeat(3, minmax(0, 1fr))' }, gap: 2 }}><StatCard title={t('fleet.summary.total')} value={hosts.length} caption={t('fleet.summary.totalHint')} icon={<ComputerRounded />} /><StatCard title={t('fleet.summary.health')} value={hosts.length ? `${Math.round(online / hosts.length * 100)}%` : '--'} caption={t('fleet.summary.healthHint')} icon={<SpeedRounded />} color="success"/><StatCard title={t('fleet.summary.attention')} value={attention} caption={t('fleet.summary.attentionHint')} icon={<SecurityRounded />} color="warning" /></Box>
    {hosts.length ? <Box sx={{ display: 'grid', gridTemplateColumns: 'repeat(auto-fill, minmax(min(100%, 285px), 1fr))', gap: 2 }}>
      {hosts.map(host => { const telemetry = host.telemetry || {}; const cpu = Number(telemetry.cpu?.usage || 0); const memory = Number(telemetry.memory?.percent || 0); const power = telemetry.hardware?.power?.totalWatts;
        return <Card key={host.id} sx={{ position: 'relative', overflow: 'hidden', borderTop: '4px solid', borderColor: host.online ? (cpu >= 85 || memory >= 90 ? 'warning.main' : 'success.main') : 'grey.400' }}><CardActionArea onClick={() => selectHost(host.id, 'dashboard')} sx={{ height: '100%' }}><CardContent><Stack direction="row" justifyContent="space-between" spacing={1}><Box sx={{ minWidth: 0 }}><Typography variant="h6" noWrap>{host.displayName}</Typography><Typography variant="body2" color="text.secondary" noWrap>{host.platform || 'Windows'} · Agent {host.version || '--'}</Typography></Box><StatusChip online={host.online} label={host.online ? t('common.online') : t('common.offline')} /></Stack><Divider sx={{ my: 2 }} />
          <Box sx={{ display: 'grid', gridTemplateColumns: 'repeat(2, minmax(0, 1fr))', gap: 1.5 }}><MetricMini label="CPU" value={telemetry.cpu ? percent(cpu) : '--'} /><MetricMini label="RAM" value={telemetry.memory ? percent(memory) : '--'} />{power !== undefined && <MetricMini label="POWER" value={watts(power)} />}</Box>
          <Typography variant="caption" color="text.secondary" sx={{ display: 'block', mt: 2 }}>{t('fleet.lastSeen', { time: host.lastSeen ? new Date(host.lastSeen).toLocaleString(lang === 'vi' ? 'vi-VN' : 'en-US') : t('common.never') })}</Typography>
        </CardContent></CardActionArea></Card>;
      })}</Box> : <Paper variant="outlined" sx={{ p: 7, textAlign: 'center' }}><ComputerRounded color="disabled" sx={{ fontSize: 54 }}/><Typography variant="h6" sx={{ mt: 2 }}>{t('fleet.emptyTitle')}</Typography><Typography color="text.secondary">{t('fleet.emptyDescription')}</Typography></Paper>}
  </Stack>;
}

function MetricMini({ label, value }) { return <Box><Typography variant="caption" color="text.secondary" sx={{ fontWeight: 700, letterSpacing: .6 }}>{label}</Typography><Typography className="metric-value" variant="h5">{value}</Typography></Box>; }

function DashboardPage({ host, api, t, lang, notify }) {
  const [history, setHistory] = useState([]); const telemetry = host?.telemetry; const hardware = telemetry?.hardware || {}; const temperatures = Array.isArray(hardware.temperatures) ? hardware.temperatures : []; const hottest = temperatures.reduce((current, item) => !current || Number(item.celsius) > Number(current.celsius) ? item : current, null);
  useEffect(() => { if (!host?.id) { setHistory([]); return; } let alive = true; api(`/api/v1/hosts/${host.id}/telemetry?from=${encodeURIComponent(new Date(Date.now() - 3600000).toISOString())}&limit=1000`).then(data => alive && setHistory(data)).catch(error => notify(error.message, 'error')); return () => { alive = false; }; }, [host?.id, api, notify]);
  if (!host) return <Paper variant="outlined" sx={{ p: 6, textAlign: 'center' }}><Typography>{t('host.none')}</Typography></Paper>;
  const metrics = [{ title: t('dashboard.cpuLoad'), value: telemetry?.cpu ? percent(telemetry.cpu.usage) : '--', caption: telemetry?.cpu?.model || t('dashboard.waiting'), icon: <MemoryRounded />, color: 'primary' }, { title: t('dashboard.memory'), value: telemetry?.memory ? percent(telemetry.memory.percent) : '--', caption: telemetry?.memory ? t('dashboard.memoryUsage', { used: bytes(telemetry.memory.used), total: bytes(telemetry.memory.total) }) : t('dashboard.waiting'), icon: <SpeedRounded />, color: 'info' }, { title: t('dashboard.uptime'), value: telemetry?.uptime !== undefined ? uptime(telemetry.uptime, lang) : '--', caption: telemetry?.os || t('dashboard.waiting'), icon: <TimelineRounded />, color: 'secondary' }, { title: t('dashboard.network'), value: telemetry?.network ? `${bytes(telemetry.network.recvPerSecond)}/s` : '--', caption: telemetry?.network ? t('dashboard.sentRate', { rate: bytes(telemetry.network.sentPerSecond) }) : t('dashboard.waiting'), icon: <NetworkCheckRounded />, color: 'info' }, { title: t('dashboard.temperature'), value: hottest ? temperature(hottest.celsius) : '--', caption: hottest?.name || t('dashboard.sensorUnavailable'), icon: <ThermostatRounded />, color: 'warning' }, { title: t('dashboard.power'), value: hardware?.power?.totalWatts !== undefined ? watts(hardware.power.totalWatts) : '--', caption: hardware?.power?.coverage === 'system-meter' ? t('dashboard.hardwareSystemMeter') : t('dashboard.hardwarePartial'), icon: <BoltRounded />, color: 'warning' }];
  return <Stack spacing={3}><Card sx={{ color: 'common.white', border: 0, backgroundImage: 'linear-gradient(195deg, #344767 0%, #1d2236 100%), radial-gradient(circle at 88% 15%, rgba(130,94,228,.38), transparent 26%)' }}><CardContent sx={{ p: { xs: 2.5, md: 3.5 }, '&:last-child': { pb: { xs: 2.5, md: 3.5 } } }}><Stack direction={{ xs: 'column', md: 'row' }} justifyContent="space-between" spacing={3}><Stack direction="row" spacing={2} alignItems="center" sx={{ minWidth: 0 }}><Avatar variant="rounded" sx={{ flexShrink: 0, width: 58, height: 58, borderRadius: 2.25, color: 'common.white', fontWeight: 800, backgroundImage: 'linear-gradient(195deg, #5e72e4, #825ee4)', boxShadow: '0 8px 18px rgba(0,0,0,.18)' }}>{initials(host.displayName)}</Avatar><Box sx={{ minWidth: 0 }}><Typography variant="h4" sx={{ overflowWrap: 'anywhere' }}>{host.displayName}</Typography><Typography sx={{ opacity: .7, overflowWrap: 'anywhere' }}>{host.hostname} · {host.platform}</Typography></Box></Stack><Stack alignItems={{ xs: 'flex-start', md: 'flex-end' }} spacing={1} sx={{ minWidth: 0 }}><StatusChip online={host.online} label={host.online ? t('common.online') : t('common.offline')} /><Typography variant="body2" sx={{ opacity: .7, overflowWrap: 'anywhere' }}>{telemetry ? t('dashboard.updatedAt', { time: new Date(host.lastSeen).toLocaleString(lang === 'vi' ? 'vi-VN' : 'en-US') }) : t('dashboard.waiting')}</Typography></Stack></Stack></CardContent></Card>
    <Box sx={{ display: 'grid', gridTemplateColumns: { xs: '1fr', sm: 'repeat(2, minmax(0, 1fr))', lg: 'repeat(3, minmax(0, 1fr))' }, gap: 2 }}>{metrics.map(item => <StatCard key={item.title} {...item} />)}</Box>
    <Box sx={{ display: 'grid', gridTemplateColumns: { xs: '1fr', lg: 'repeat(2, minmax(0, 1fr))' }, gap: 2 }}><Card><CardContent><LineChart title={t('dashboard.cpuTrend')} values={history.map(item => Number(item.cpu?.usage || 0))} empty={t('common.noData')} /></CardContent></Card><Card><CardContent><LineChart title={t('dashboard.memoryTrend')} values={history.map(item => Number(item.memory?.percent || 0))} color="#00b8d9" empty={t('common.noData')} /></CardContent></Card></Box>
    <Box sx={{ display: 'grid', gridTemplateColumns: { xs: '1fr', lg: 'minmax(0, 1fr) minmax(0, 1fr)' }, gap: 2 }}><Card><CardContent><Typography variant="h6">{t('dashboard.storage')}</Typography><Stack spacing={2} sx={{ mt: 2 }}>{(telemetry?.disk || []).length ? telemetry.disk.map(disk => { const used = Number(disk.total) ? Number(disk.used) / Number(disk.total) * 100 : 0; return <Box key={disk.drive} sx={{ minWidth: 0 }}><Stack direction="row" justifyContent="space-between" spacing={1.5}><Typography fontWeight={700} sx={{ minWidth: 0, overflow: 'hidden', textOverflow: 'ellipsis', whiteSpace: 'nowrap' }}>{disk.drive}</Typography><Typography variant="body2" color="text.secondary" sx={{ flexShrink: 0 }}>{bytes(disk.used)} / {bytes(disk.total)}</Typography></Stack><LinearProgress color={used >= 90 ? 'error' : used >= 80 ? 'warning' : 'primary'} variant="determinate" value={used} sx={{ mt: .75, height: 8, borderRadius: 4 }} /></Box>; }) : <Typography color="text.secondary">{t('dashboard.noDisks')}</Typography>}</Stack></CardContent></Card>
      <Card><CardContent><Typography variant="h6">{t('dashboard.identity')}</Typography><Stack spacing={1.3} sx={{ mt: 2 }}>{[['machine.hostname', host.hostname], ['machine.platform', host.platform], ['machine.agentVersion', host.version], ['machine.lastSeen', host.lastSeen ? new Date(host.lastSeen).toLocaleString(lang === 'vi' ? 'vi-VN' : 'en-US') : '--'], ['machine.fingerprint', host.fingerprint]].map(([label, value]) => <Stack direction="row" justifyContent="space-between" spacing={2} key={label} sx={{ minWidth: 0 }}><Typography color="text.secondary" sx={{ flexShrink: 0 }}>{t(label)}</Typography><Typography sx={{ minWidth: 0, textAlign: 'right', overflowWrap: 'anywhere' }}>{value || '--'}</Typography></Stack>)}</Stack></CardContent></Card></Box>
    <Card><CardContent><Stack direction={{ xs: 'column', sm: 'row' }} justifyContent="space-between" spacing={1}><Typography variant="h6">{t('dashboard.hardwareSensors')}</Typography><Typography variant="caption" color="text.secondary">{hardware?.power?.coverage === 'complete' ? t('dashboard.hardwareComplete') : t('dashboard.hardwarePartial')}</Typography></Stack><Box sx={{ mt: 2, display: 'grid', gridTemplateColumns: 'repeat(auto-fit, minmax(min(100%, 180px), 1fr))', gap: 1.5 }}>{temperatures.length ? temperatures.map(sensor => <Paper key={sensor.id} variant="outlined" sx={{ p: 2, minWidth: 0 }}><Typography variant="subtitle2" sx={{ overflowWrap: 'anywhere' }}>{sensor.name}</Typography><Typography variant="h5" color={Number(sensor.celsius) >= 85 ? 'error.main' : Number(sensor.celsius) >= 70 ? 'warning.main' : 'text.primary'}>{temperature(sensor.celsius)}</Typography><Typography variant="caption" color="text.secondary" sx={{ overflowWrap: 'anywhere' }}>{sensor.source || '--'}</Typography></Paper>) : <Typography color="text.secondary">{t('dashboard.noHardwareSensors')}</Typography>}</Box></CardContent></Card>
  </Stack>;
}

function ProcessActions({ host, item, canManage, t, send }) {
  if (!canManage) return null;
  return <Stack direction="row" spacing={.5} justifyContent="flex-end" flexWrap="wrap"><>{host.capabilities?.includes('window.capture') && <Tooltip title={t('process.capture')}><IconButton size="small" onClick={() => send('window.capture', { processName: item.name })}><CameraAltRounded fontSize="small" /></IconButton></Tooltip>}</><Tooltip title={t('process.kill')}><IconButton size="small" color="error" onClick={() => window.confirm(t('process.killConfirm', { name: item.name, pid: item.pid })) && send('process.kill', { pid: Number(item.pid) })}><CloseRounded fontSize="small" /></IconButton></Tooltip></Stack>;
}

function ProcessesPage({ host, processes, onProcessesLoaded, api, canManage, t, notify }) {
  const [query, setQuery] = useState(''); const supported = Boolean(host?.capabilities?.includes('processes'));
  const load = async () => { if (!host?.id) return; try { const data = await api(`/api/v1/hosts/${host.id}/processes`); onProcessesLoaded(host.id, data.processes || []); if (data.commandId) notify(t('process.refreshRequested')); } catch (error) { notify(t(`error.${error.message}`), 'error'); } };
  const send = async (type, payload) => { try { await api(`/api/v1/hosts/${host.id}/commands`, { method: 'POST', body: JSON.stringify({ type, payload }) }); notify(t('command.queued'), 'success'); } catch (error) { notify(t(`error.${error.message}`), 'error'); } };
  const filtered = processes.filter(item => `${item.name} ${item.path || ''}`.toLowerCase().includes(query.toLowerCase()));
  const actions = item => <ProcessActions host={host} item={item} canManage={canManage} t={t} send={send} />;
  const empty = !supported ? t('process.unsupported') : t('process.none');
  return <Stack spacing={3}><Stack direction={{ xs: 'column', sm: 'row' }} justifyContent="space-between" spacing={2}><Box sx={{ minWidth: 0 }}><Typography variant="h4">{t('process.title')}</Typography><Typography color="text.secondary">{t('process.description')}</Typography></Box><Stack direction={{ xs: 'column', sm: 'row' }} spacing={1} sx={{ width: { xs: '100%', sm: 'auto' }, flexShrink: 0 }}><TextField fullWidth size="small" placeholder={t('process.search')} value={query} onChange={event => setQuery(event.target.value)} InputProps={{ startAdornment: <InputAdornment position="start"><SearchRounded /></InputAdornment> }} sx={{ minWidth: { sm: 240 } }} /><Button disabled={!supported} variant="contained" onClick={load} startIcon={<RefreshRounded />} sx={{ whiteSpace: 'nowrap' }}>{t('process.fetch')}</Button></Stack></Stack>
    <Box sx={{ display: { xs: 'grid', md: 'none' }, gap: 1.25 }}>{!supported || !filtered.length ? <Paper variant="outlined" sx={{ p: 3, textAlign: 'center' }}><Typography color="text.secondary">{empty}</Typography></Paper> : filtered.map(item => <Paper key={`${item.pid}-${item.name}`} variant="outlined" sx={{ p: 2, minWidth: 0 }}><Stack direction="row" spacing={1.25} alignItems="flex-start"><Avatar variant="rounded" sx={{ flexShrink: 0, width: 34, height: 34, bgcolor: 'primary.lighter', color: 'primary.main', fontSize: 13 }}>{initials(item.name).slice(0, 1)}</Avatar><Box sx={{ minWidth: 0, flex: 1 }}><Typography fontWeight={700} sx={{ overflowWrap: 'anywhere' }}>{item.name}</Typography><Typography variant="caption" color="text.secondary">PID {item.pid}</Typography></Box>{actions(item)}</Stack><Box sx={{ display: 'grid', gridTemplateColumns: 'repeat(2, minmax(0, 1fr))', gap: 1.25, mt: 2 }}><Box><Typography variant="caption" color="text.secondary">{t('process.cpu')}</Typography><Typography className="metric-value" fontWeight={700}>{Number(item.cpuPercent || 0).toFixed(1)}%</Typography></Box><Box><Typography variant="caption" color="text.secondary">{t('process.memory')}</Typography><Typography className="metric-value" fontWeight={700}>{Number(item.memoryMB || 0).toFixed(1)} MB</Typography></Box></Box><Typography variant="caption" color="text.secondary" sx={{ display: 'block', mt: 1.5, overflowWrap: 'anywhere' }}>{item.path || '-'}</Typography></Paper>)}</Box>
    <Card sx={{ display: { xs: 'none', md: 'block' }, minWidth: 0 }}><TableContainer sx={{ maxWidth: '100%', overflowX: 'auto' }}><Table className="data-table" size="small" sx={{ minWidth: 760 }}><TableHead><TableRow><TableCell>{t('process.name')}</TableCell><TableCell>{t('process.pid')}</TableCell><TableCell>{t('process.cpu')}</TableCell><TableCell>{t('process.memory')}</TableCell><TableCell>{t('process.path')}</TableCell><TableCell align="right">{t('common.actions')}</TableCell></TableRow></TableHead><TableBody>{!supported || !filtered.length ? <TableRow><TableCell colSpan={6}>{empty}</TableCell></TableRow> : filtered.map(item => <TableRow key={`${item.pid}-${item.name}`} hover><TableCell><Stack direction="row" alignItems="center" spacing={1}><Avatar variant="rounded" sx={{ width: 28, height: 28, bgcolor: 'primary.lighter', color: 'primary.main', fontSize: 12 }}>{initials(item.name).slice(0, 1)}</Avatar><Typography fontWeight={700}>{item.name}</Typography></Stack></TableCell><TableCell>{item.pid}</TableCell><TableCell>{Number(item.cpuPercent || 0).toFixed(1)}%</TableCell><TableCell>{Number(item.memoryMB || 0).toFixed(1)} MB</TableCell><TableCell sx={{ maxWidth: 260, overflow: 'hidden', textOverflow: 'ellipsis' }}>{item.path || '-'}</TableCell><TableCell align="right">{actions(item)}</TableCell></TableRow>)}</TableBody></Table></TableContainer></Card>
  </Stack>;
}

function WatchdogPage({ host, api, canManage, t, notify }) {
  const [watchdog, setWatchdog] = useState({ version: 0, rules: [] }); const [editing, setEditing] = useState(null); const supported = Boolean(host?.capabilities?.includes('watchdog'));
  const load = useCallback(async () => { if (!host?.id || !supported) { setWatchdog({ version: 0, rules: [] }); return; } try { setWatchdog(await api(`/api/v1/hosts/${host.id}/watchdog`)); } catch (error) { notify(t(`error.${error.message}`), 'error'); } }, [host?.id, supported, api, notify, t]);
  useEffect(() => { load(); }, [load]);
  const save = async rule => { const rules = watchdog.rules.filter(item => item.id !== rule.id).concat(rule); try { const result = await api(`/api/v1/hosts/${host.id}/watchdog`, { method: 'PUT', body: JSON.stringify({ rules }) }); setWatchdog(result); setEditing(null); notify(t('watchdog.configSent'), 'success'); } catch (error) { notify(t(`error.${error.message}`), 'error'); } };
  const deleteRule = async rule => { const rules = watchdog.rules.filter(item => item.id !== rule.id); try { setWatchdog(await api(`/api/v1/hosts/${host.id}/watchdog`, { method: 'PUT', body: JSON.stringify({ rules }) })); } catch (error) { notify(t(`error.${error.message}`), 'error'); } };
  const launch = async id => { try { await api(`/api/v1/hosts/${host.id}/commands`, { method: 'POST', body: JSON.stringify({ type: 'watchdog.launch', payload: { ruleId: id } }) }); notify(t('command.queued'), 'success'); } catch (error) { notify(t(`error.${error.message}`), 'error'); } };
  return <Stack spacing={3}><Stack direction={{ xs: 'column', sm: 'row' }} justifyContent="space-between" spacing={2}><Box><Typography variant="h4">{t('watchdog.title')}</Typography><Typography color="text.secondary">{t('watchdog.description')}</Typography></Box>{canManage && supported && <Button variant="contained" startIcon={<AddRounded />} onClick={() => setEditing({ id: crypto.randomUUID(), processName: '', filePath: '', runMode: host.capabilities?.includes('desktop-helper') ? 'interactive' : 'service', enabled: true, captureAfterLaunch: true })}>{t('watchdog.add')}</Button>}</Stack>
    <Alert icon={<SecurityRounded />} severity="info"><Typography fontWeight={700}>{t('watchdog.localFirst')}</Typography><Typography variant="body2">{t('watchdog.localFirstDescription')}</Typography></Alert>{!supported ? <Paper variant="outlined" sx={{ p: 5, textAlign: 'center' }}>{t('watchdog.unsupported')}</Paper> : watchdog.rules.length ? <Stack spacing={1.5}>{watchdog.rules.map(rule => <Card key={rule.id}><CardContent><Stack direction={{ xs: 'column', sm: 'row' }} justifyContent="space-between" spacing={2}><Box sx={{ minWidth: 0 }}><Stack direction="row" spacing={1} alignItems="center" flexWrap="wrap" useFlexGap><Typography variant="h6" sx={{ overflowWrap: 'anywhere' }}>{rule.processName}</Typography><StatusChip online={rule.enabled !== false} label={t(rule.enabled !== false ? 'watchdog.enabled' : 'watchdog.disabled')} /></Stack><Typography variant="body2" color="text.secondary" sx={{ mt: .6, overflowWrap: 'anywhere' }}>{rule.filePath || t('common.pathHidden')}</Typography><Stack direction="row" spacing={1} flexWrap="wrap" useFlexGap sx={{ mt: 1 }}><Chip size="small" label={t(rule.runMode === 'service' ? 'watchdog.service' : 'watchdog.interactive')} /><Chip size="small" variant="outlined" label={t(rule.captureAfterLaunch === false ? 'watchdog.captureDisabled' : 'watchdog.captureEnabled')} /></Stack></Box>{canManage && <Stack direction="row" spacing={1} alignSelf={{ xs: 'flex-start', sm: 'center' }}><Button size="small" variant="contained" onClick={() => launch(rule.id)} startIcon={<PlayArrowRounded />}>{t('watchdog.launch')}</Button><IconButton onClick={() => setEditing(rule)}><EditRounded /></IconButton><IconButton color="error" onClick={() => deleteRule(rule)}><DeleteOutlineRounded /></IconButton></Stack>}</Stack></CardContent></Card>)}</Stack> : <Paper variant="outlined" sx={{ p: 5, textAlign: 'center' }}><Typography variant="h6">{t('watchdog.emptyTitle')}</Typography><Typography color="text.secondary">{t('watchdog.emptyDescription')}</Typography></Paper>}
    <RuleDialog rule={editing} onClose={() => setEditing(null)} onSave={save} t={t} interactive={host?.capabilities?.includes('desktop-helper')} capture={host?.capabilities?.includes('window.capture')} />
  </Stack>;
}

function RuleDialog({ rule, onClose, onSave, t, interactive, capture }) {
  const [form, setForm] = useState(rule); useEffect(() => setForm(rule), [rule]); if (!form) return null; const set = (key, value) => setForm(current => ({ ...current, [key]: value }));
  return <Dialog open onClose={onClose} fullWidth maxWidth="sm"><Box component="form" onSubmit={event => { event.preventDefault(); onSave(form); }}><DialogTitle>{form.processName ? t('watchdog.editTitle') : t('watchdog.addTitle')}</DialogTitle><DialogContent><TextField fullWidth required label={t('watchdog.processName')} value={form.processName} onChange={event => set('processName', event.target.value)} sx={{ mt: 1 }}/><TextField fullWidth required label={t('watchdog.executablePath')} value={form.filePath} onChange={event => set('filePath', event.target.value)} sx={{ mt: 2 }}/><TextField fullWidth select label={t('watchdog.runMode')} value={form.runMode} onChange={event => set('runMode', event.target.value)} sx={{ mt: 2 }}><MenuItem value="interactive" disabled={!interactive}>{t('watchdog.interactive')}</MenuItem><MenuItem value="service">{t('watchdog.service')}</MenuItem></TextField><FormControlLabel sx={{ mt: 1, mr: 0, alignItems: 'flex-start' }} control={<Switch checked={form.enabled !== false} onChange={event => set('enabled', event.target.checked)} />} label={t('watchdog.enableRestart')} /><FormControlLabel sx={{ mr: 0, alignItems: 'flex-start' }} control={<Switch checked={form.captureAfterLaunch !== false} disabled={!capture} onChange={event => set('captureAfterLaunch', event.target.checked)} />} label={t('watchdog.captureAfter')} /></DialogContent><DialogActions sx={{ px: 3, pb: 2.5, flexWrap: 'wrap', gap: 1 }}><Button onClick={onClose}>{t('common.cancel')}</Button><Button type="submit" variant="contained">{t('watchdog.save')}</Button></DialogActions></Box></Dialog>;
}

function ActivityPage({ host, api, t, lang, notify }) {
  const [events, setEvents] = useState([]); const [commands, setCommands] = useState([]);
  const load = useCallback(async () => { if (!host?.id) { setEvents([]); setCommands([]); return; } try { const [nextEvents, nextCommands] = await Promise.all([api(`/api/v1/hosts/${host.id}/events`), api(`/api/v1/hosts/${host.id}/commands`)]); setEvents(nextEvents); setCommands(nextCommands); } catch (error) { notify(t(`error.${error.message}`), 'error'); } }, [host?.id, api, notify, t]);
  useEffect(() => { load(); }, [load]); const date = value => value ? new Date(value).toLocaleString(lang === 'vi' ? 'vi-VN' : 'en-US') : '--';
  return <Stack spacing={3}><Box><Typography variant="h4">{t('activity.title')}</Typography><Typography color="text.secondary">{t('activity.description')}</Typography></Box><Box sx={{ display: 'grid', gridTemplateColumns: { xs: '1fr', lg: '1fr 1fr' }, gap: 2 }}><TimelineCard title={t('activity.events')} items={events.map(item => ({ title: t(`event.${item.type}`) === `event.${item.type}` ? item.type : t(`event.${item.type}`), subtitle: item.payload?.message || item.type, date: date(item.occurredAt), severity: item.severity }))} empty={t('activity.noEvents')} /><TimelineCard title={t('activity.commands')} items={commands.map(item => ({ title: `${t(`command.type.${item.type}`)} · ${t(`status.${item.status}`)}`, subtitle: t('activity.requestedBy', { user: item.requestedBy }), date: date(item.requestedAt), severity: item.status === 'failed' ? 'error' : item.status === 'succeeded' ? 'success' : 'info' }))} empty={t('activity.noCommands')} /></Box></Stack>;
}

function TimelineCard({ title, items, empty }) { return <Card><CardContent><Typography variant="h6">{title}</Typography><Stack divider={<Divider flexItem />} sx={{ mt: 2 }}>{items.length ? items.map((item, index) => <Stack key={`${item.title}-${index}`} direction="row" spacing={1.5} sx={{ py: 1.25 }}><Avatar sx={{ flexShrink: 0, width: 10, height: 10, mt: .75, bgcolor: item.severity === 'error' ? 'error.main' : item.severity === 'success' ? 'success.main' : 'info.main' }} /><Box sx={{ minWidth: 0 }}><Typography variant="subtitle2" sx={{ overflowWrap: 'anywhere' }}>{item.title}</Typography><Typography variant="body2" color="text.secondary" sx={{ overflowWrap: 'anywhere' }}>{item.subtitle}</Typography><Typography variant="caption" color="text.disabled">{item.date}</Typography></Box></Stack>) : <Typography color="text.secondary" sx={{ py: 3 }}>{empty}</Typography>}</Stack></CardContent></Card>; }

function AdminPage({ hosts, api, t, lang, notify, selectHost }) {
  const [agents, setAgents] = useState([]); const [pending, setPending] = useState([]); const [users, setUsers] = useState([]); const [settings, setSettings] = useState({ discordWebhook: '' }); const [agentEdit, setAgentEdit] = useState(null); const [userEdit, setUserEdit] = useState(null);
  const load = useCallback(async () => { try { const [allAgents, waiting, allUsers, nextSettings] = await Promise.all([api('/api/v1/agents'), api('/api/v1/agents/pending'), api('/api/v1/users'), api('/api/v1/settings')]); setAgents(allAgents); setPending(waiting); setUsers(allUsers); setSettings(nextSettings); } catch (error) { notify(t(`error.${error.message}`), 'error'); } }, [api, notify, t]); useEffect(() => { load(); }, [load]);
  const approve = async agent => { const name = window.prompt(t('admin.displayNamePrompt'), agent.hostname); if (!name) return; try { await api(`/api/v1/agents/${agent.id}/approve`, { method: 'POST', body: JSON.stringify({ displayName: name }) }); notify(t('admin.approved'), 'success'); load(); } catch (error) { notify(t(`error.${error.message}`), 'error'); } };
  const revoke = async agent => { if (!window.confirm(t('admin.revokeConfirm', { host: agent.displayName || agent.hostname }))) return; try { await api(`/api/v1/agents/${agent.id}/revoke`, { method: 'POST', body: '{}' }); notify(t('admin.agentRevoked')); load(); } catch (error) { notify(t(`error.${error.message}`), 'error'); } };
  const saveSettings = async event => { event.preventDefault(); try { await api('/api/v1/settings', { method: 'PUT', body: JSON.stringify({ discordWebhook: settings.discordWebhook || '' }) }); notify(t('admin.settingsSaved'), 'success'); } catch (error) { notify(t(`error.${error.message}`), 'error'); } };
  return <Stack spacing={3}><Box><Typography variant="h4">{t('admin.title')}</Typography><Typography color="text.secondary">{t('admin.description')}</Typography></Box><Box sx={{ display: 'grid', gridTemplateColumns: { xs: '1fr', lg: '2fr 1fr' }, gap: 2 }}><Card><CardContent><Typography variant="h6">{t('admin.agents')}</Typography><Stack spacing={1.5} sx={{ mt: 2 }}>{agents.length ? agents.map(agent => <Paper key={agent.id} variant="outlined" sx={{ p: 1.75, minWidth: 0 }}><Stack direction={{ xs: 'column', sm: 'row' }} justifyContent="space-between" spacing={1}><Box sx={{ minWidth: 0 }}><Stack direction="row" spacing={1} alignItems="center" flexWrap="wrap" useFlexGap><Typography fontWeight={700} sx={{ overflowWrap: 'anywhere' }}>{agent.displayName || agent.hostname}</Typography><StatusChip online={agent.status === 'approved' && agent.online} label={agent.status === 'approved' ? (agent.online ? t('agent.status.online') : t('agent.status.offline')) : t(`agent.status.${agent.status}`)} /></Stack><Typography variant="body2" color="text.secondary" sx={{ overflowWrap: 'anywhere' }}>{agent.hostname} · {agent.platform} · {agent.version}</Typography>{agent.notes && <Typography variant="caption" color="text.secondary" sx={{ overflowWrap: 'anywhere' }}>{agent.notes}</Typography>}</Box><Stack direction="row" spacing={.5} alignSelf="flex-start"><Tooltip title={t('common.edit')}><IconButton size="small" onClick={() => setAgentEdit(agent)}><EditRounded fontSize="small" /></IconButton></Tooltip>{agent.status !== 'revoked' && <Tooltip title={t('admin.revokeAgent')}><IconButton size="small" color="error" onClick={() => revoke(agent)}><DeleteOutlineRounded fontSize="small" /></IconButton></Tooltip>}</Stack></Stack></Paper>) : <Typography color="text.secondary">{t('admin.noAgents')}</Typography>}</Stack></CardContent></Card>
    <Card><CardContent><Typography variant="h6">{t('admin.pending')}</Typography><Typography variant="body2" color="text.secondary">{t('admin.verify')}</Typography><Stack spacing={1.5} sx={{ mt: 2 }}>{pending.length ? pending.map(agent => <Paper key={agent.id} variant="outlined" sx={{ p: 1.5 }}><Typography fontWeight={700} sx={{ overflowWrap: 'anywhere' }}>{agent.hostname}</Typography><Typography variant="caption" sx={{ display: 'block', overflowWrap: 'anywhere' }}>{agent.fingerprint}</Typography><Stack direction="row" spacing={1} flexWrap="wrap" useFlexGap sx={{ mt: 1.5 }}><Button size="small" color="error" onClick={() => revoke(agent)}>{t('admin.reject')}</Button><Button size="small" variant="contained" onClick={() => approve(agent)}>{t('admin.approve')}</Button></Stack></Paper>) : <Typography color="text.secondary">{t('admin.noPending')}</Typography>}</Stack></CardContent></Card></Box>
    <Box sx={{ display: 'grid', gridTemplateColumns: { xs: '1fr', lg: '1fr 1fr' }, gap: 2 }}><Card><CardContent><Stack direction={{ xs: 'column', sm: 'row' }} justifyContent="space-between" alignItems={{ xs: 'flex-start', sm: 'center' }} spacing={1}><Typography variant="h6">{t('admin.users')}</Typography><Button size="small" startIcon={<AddRounded />} onClick={() => setUserEdit({ username: '', password: '', role: 'viewer', hostIds: [] })}>{t('admin.addUser')}</Button></Stack><Stack spacing={1} sx={{ mt: 2 }}>{users.map(user => <Paper variant="outlined" sx={{ p: 1.3, minWidth: 0 }} key={user.username}><Stack direction="row" justifyContent="space-between" spacing={1}><Box sx={{ minWidth: 0 }}><Typography fontWeight={700} sx={{ overflowWrap: 'anywhere' }}>{user.username}</Typography><Typography variant="caption" color="text.secondary" sx={{ display: 'block', overflowWrap: 'anywhere' }}>{t(`role.${user.role === 'super_admin' ? 'superAdmin' : user.role}`)} · {user.role === 'super_admin' ? t('user.allHosts') : t('user.hostCount', { count: user.hostIds?.length || 0, names: (user.hostIds || []).map(id => hosts.find(host => host.id === id)?.displayName).filter(Boolean).join(', ') || t('user.noHosts') })}</Typography></Box><Stack direction="row" flexShrink={0}><IconButton size="small" onClick={() => setUserEdit({ ...user, password: '' })}><EditRounded fontSize="small" /></IconButton><IconButton disabled={user.username === JSON.parse(localStorage.getItem('wc_user') || '{}').username} size="small" color="error" onClick={async () => { if (!window.confirm(t('admin.deleteUserConfirm', { user: user.username }))) return; await api(`/api/v1/users/${encodeURIComponent(user.username)}`, { method: 'DELETE' }); load(); }}><DeleteOutlineRounded fontSize="small" /></IconButton></Stack></Stack></Paper>)}</Stack></CardContent></Card>
      <Card><CardContent component="form" onSubmit={saveSettings}><Typography variant="h6">{t('admin.integrations')}</Typography><Typography variant="body2" color="text.secondary" sx={{ mt: .5 }}>{t('admin.webhookCentral')}</Typography><TextField fullWidth type="url" label={t('admin.discordWebhook')} value={settings.discordWebhook || ''} onChange={event => setSettings(current => ({ ...current, discordWebhook: event.target.value }))} sx={{ mt: 2 }} /><Button type="submit" variant="contained" sx={{ mt: 2 }}>{t('admin.saveSettings')}</Button></CardContent></Card></Box>
    <AgentDialog agent={agentEdit} t={t} onClose={() => setAgentEdit(null)} onSave={async values => { try { await api(`/api/v1/agents/${values.id}`, { method: 'PUT', body: JSON.stringify({ displayName: values.displayName, notes: values.notes }) }); setAgentEdit(null); notify(t('admin.agentUpdated'), 'success'); load(); } catch (error) { notify(t(`error.${error.message}`), 'error'); } }} /><UserDialog user={userEdit} hosts={hosts} t={t} onClose={() => setUserEdit(null)} onSave={async values => { try { const editing = Boolean(values.originalUsername); const body = { role: values.role, hostIds: values.hostIds }; if (editing) { if (values.password) body.password = values.password; await api(`/api/v1/users/${encodeURIComponent(values.originalUsername)}`, { method: 'PUT', body: JSON.stringify(body) }); } else { body.username = values.username; body.password = values.password; await api('/api/v1/users', { method: 'POST', body: JSON.stringify(body) }); } setUserEdit(null); notify(t(editing ? 'user.updated' : 'user.created'), 'success'); load(); } catch (error) { notify(t(`error.${error.message}`), 'error'); } }} />
  </Stack>;
}

function AgentDialog({ agent, t, onClose, onSave }) { const [form, setForm] = useState(agent); useEffect(() => setForm(agent), [agent]); if (!form) return null; return <Dialog open onClose={onClose} fullWidth maxWidth="sm"><Box component="form" onSubmit={event => { event.preventDefault(); onSave(form); }}><DialogTitle>{t('agent.editTitle')}</DialogTitle><DialogContent><TextField fullWidth required label={t('agent.displayName')} value={form.displayName || ''} onChange={event => setForm(current => ({ ...current, displayName: event.target.value }))} sx={{ mt: 1 }} /><TextField fullWidth multiline rows={4} inputProps={{ maxLength: 500 }} label={t('agent.notes')} value={form.notes || ''} onChange={event => setForm(current => ({ ...current, notes: event.target.value }))} sx={{ mt: 2 }} /></DialogContent><DialogActions sx={{ px: 3, pb: 2.5, flexWrap: 'wrap', gap: 1 }}><Button onClick={onClose}>{t('common.cancel')}</Button><Button variant="contained" type="submit">{t('common.save')}</Button></DialogActions></Box></Dialog>; }

function UserDialog({ user, hosts, t, onClose, onSave }) { const [form, setForm] = useState(null); useEffect(() => { if (user) setForm({ ...user, originalUsername: user.username || null, hostIds: user.hostIds || [] }); }, [user]); if (!form) return null; const set = (key, value) => setForm(current => ({ ...current, [key]: value })); const superAdmin = form.role === 'super_admin'; return <Dialog open onClose={onClose} fullWidth maxWidth="sm"><Box component="form" onSubmit={event => { event.preventDefault(); onSave(form); }}><DialogTitle>{form.originalUsername ? t('user.editTitle') : t('user.addTitle')}</DialogTitle><DialogContent><TextField fullWidth required disabled={Boolean(form.originalUsername)} label={t('user.username')} value={form.username || ''} onChange={event => set('username', event.target.value)} sx={{ mt: 1 }} /><TextField fullWidth required={!form.originalUsername} type="password" inputProps={{ minLength: 10 }} label={t('user.password')} value={form.password || ''} onChange={event => set('password', event.target.value)} sx={{ mt: 2 }} /><TextField fullWidth select label={t('user.role')} value={form.role} onChange={event => set('role', event.target.value)} sx={{ mt: 2 }}><MenuItem value="viewer">{t('user.viewer')}</MenuItem><MenuItem value="admin">{t('user.admin')}</MenuItem><MenuItem value="super_admin">{t('user.superAdmin')}</MenuItem></TextField><Typography variant="subtitle2" sx={{ mt: 2 }}>{t('user.hostAccess')}</Typography><Typography variant="caption" color="text.secondary">{t(superAdmin ? 'user.superAdminHosts' : 'user.hostAccessHelp')}</Typography><Stack sx={{ mt: 1 }} spacing={.5}>{hosts.map(host => <FormControlLabel disabled={superAdmin} key={host.id} sx={{ mr: 0, alignItems: 'flex-start' }} control={<Switch checked={superAdmin || form.hostIds.includes(host.id)} onChange={event => set('hostIds', event.target.checked ? [...form.hostIds, host.id] : form.hostIds.filter(id => id !== host.id))} />} label={host.displayName} />)}</Stack></DialogContent><DialogActions sx={{ px: 3, pb: 2.5, flexWrap: 'wrap', gap: 1 }}><Button onClick={onClose}>{t('common.cancel')}</Button><Button type="submit" variant="contained">{form.originalUsername ? t('user.save') : t('user.create')}</Button></DialogActions></Box></Dialog>; }

function PasswordChangeDialog({ username, api, t, onComplete }) {
  const [password, setPassword] = useState(''); const [error, setError] = useState(''); const [busy, setBusy] = useState(false);
  const submit = async event => { event.preventDefault(); setBusy(true); setError(''); try {
    await api(`/api/v1/users/${encodeURIComponent(username)}/password`, { method: 'POST', body: JSON.stringify({ password }) });
    setPassword(''); onComplete();
  } catch (err) { setError(t(`error.${err.message}`)); } finally { setBusy(false); } };
  return <Dialog open disableEscapeKeyDown onClose={() => {}} fullWidth maxWidth="sm" aria-labelledby="password-change-title"><Box component="form" onSubmit={submit}><DialogTitle id="password-change-title">{t('password.title')}</DialogTitle><DialogContent><Typography color="text.secondary">{t('password.description')}</Typography><TextField fullWidth required autoFocus type="password" autoComplete="new-password" inputProps={{ minLength: 10 }} label={t('password.new')} value={password} onChange={event => setPassword(event.target.value)} sx={{ mt: 3 }} />{error && <Alert severity="error" sx={{ mt: 2 }}>{error}</Alert>}</DialogContent><DialogActions sx={{ px: 3, pb: 2.5 }}><Button type="submit" variant="contained" disabled={busy}>{t('password.update')}</Button></DialogActions></Box></Dialog>;
}

function Navigation({ page, setPage, isSuper, t, onClose, lang, setLang, themeMode, onToggleTheme, onLogout }) {
  const entries = [{ id: 'fleet', label: t('nav.fleet'), icon: <AppsRounded /> }, { id: 'dashboard', label: t('nav.dashboard'), icon: <DashboardRounded /> }, { id: 'processes', label: t('nav.processes'), icon: <HomeRepairServiceRounded /> }, { id: 'watchdog', label: t('nav.watchdog'), icon: <SecurityRounded /> }, { id: 'activity', label: t('nav.activity'), icon: <TimelineRounded /> }, ...(isSuper ? [{ id: 'admin', label: t('nav.admin'), icon: <AdminPanelSettingsRounded /> }] : [])];
  return <Box sx={{ height: 'calc(100% - 32px)', m: 2, display: 'flex', flexDirection: 'column', p: 2, overflow: 'hidden', color: 'rgba(255,255,255,.92)', borderRadius: 3, backgroundImage: 'linear-gradient(195deg, #344767 0%, #1d2236 100%)', boxShadow: '0 10px 28px rgba(31,38,59,.28)' }}><Stack direction="row" spacing={1.3} alignItems="center" sx={{ px: 1, py: 1.25 }}><Avatar variant="rounded" sx={{ width: 38, height: 38, borderRadius: 1.75, color: 'common.white', fontWeight: 800, backgroundImage: 'linear-gradient(195deg, #5e72e4, #825ee4)', boxShadow: '0 6px 14px rgba(0,0,0,.24)' }}>WC</Avatar><Box sx={{ minWidth: 0 }}><Typography variant="subtitle1" fontWeight={800} noWrap>Windows Controller</Typography><Typography variant="caption" sx={{ color: 'rgba(255,255,255,.58)' }}>Fleet management</Typography></Box></Stack><Divider sx={{ borderColor: 'rgba(255,255,255,.11)', my: 1.5 }} /><List sx={{ py: 0, px: .25 }}>{entries.map(entry => <ListItemButton key={entry.id} selected={page === entry.id} onClick={() => { setPage(entry.id); onClose?.(); }} sx={{ borderRadius: 1.75, mb: .65, py: 1, color: 'rgba(255,255,255,.74)', '& .MuiListItemIcon-root': { color: 'rgba(255,255,255,.58)' }, '&.Mui-selected, &.Mui-selected:hover': { color: '#fff', backgroundImage: 'linear-gradient(195deg, #5e72e4, #825ee4)', boxShadow: '0 5px 13px rgba(94,114,228,.28)' }, '&.Mui-selected .MuiListItemIcon-root': { color: '#fff' } }}><ListItemIcon sx={{ minWidth: 40 }}>{entry.icon}</ListItemIcon><ListItemText primary={entry.label} primaryTypographyProps={{ fontSize: '.875rem', fontWeight: page === entry.id ? 700 : 500 }} /></ListItemButton>)}</List><Box sx={{ mt: 'auto', pt: 2 }}><Divider sx={{ borderColor: 'rgba(255,255,255,.11)', mb: 2 }} /><FormControl size="small" fullWidth><Select aria-label="Language" value={lang} onChange={event => setLang(event.target.value)} sx={{ color: 'rgba(255,255,255,.92)', borderRadius: 1.75, '& .MuiOutlinedInput-notchedOutline': { borderColor: 'rgba(255,255,255,.25)' }, '& .MuiSvgIcon-root': { color: 'rgba(255,255,255,.72)' }, '&:hover .MuiOutlinedInput-notchedOutline': { borderColor: 'rgba(255,255,255,.55)' } }}><MenuItem value="vi">Tiếng Việt</MenuItem><MenuItem value="en">English</MenuItem></Select></FormControl><Stack direction="row" spacing={1} sx={{ mt: 1.5 }}><Button fullWidth size="small" color="inherit" variant="outlined" onClick={onToggleTheme} startIcon={themeMode === 'dark' ? <Brightness7Rounded /> : <Brightness4Rounded />} sx={{ borderColor: 'rgba(255,255,255,.25)', color: 'rgba(255,255,255,.92)', '&:hover': { borderColor: 'rgba(255,255,255,.64)', bgcolor: 'rgba(255,255,255,.08)' } }}>{themeMode === 'dark' ? 'Light' : 'Dark'}</Button><Tooltip title={t('session.signOut')}><IconButton aria-label={t('session.signOut')} onClick={onLogout} sx={{ color: '#ffb8c8', border: '1px solid rgba(255,184,200,.28)', borderRadius: 1.5 }}><LogoutRounded fontSize="small" /></IconButton></Tooltip></Stack></Box></Box>;
}

function App() {
  const { lang, setLang, t } = useTranslation(); const [themeMode, setThemeMode] = useState(() => localStorage.getItem('wc_theme') || (matchMedia('(prefers-color-scheme: dark)').matches ? 'dark' : 'light')); const [token, setToken] = useState(() => localStorage.getItem('wc_token') || ''); const [user, setUser] = useState(() => { try { return JSON.parse(localStorage.getItem('wc_user') || 'null'); } catch { return null; } }); const [setupRequired, setSetupRequired] = useState(null); const [hosts, setHosts] = useState([]); const [processesByHost, setProcessesByHost] = useState({}); const [selectedId, setSelectedId] = useState(() => new URLSearchParams(location.search).get('host')); const [page, setPageState] = useState(() => location.hash.slice(1) || 'fleet'); const [socketState, setSocketState] = useState('connecting'); const [snack, setSnack] = useState(null); const [mobileOpen, setMobileOpen] = useState(false); const isMobile = useMediaQuery('(max-width:900px)');
  const notify = useCallback((message, severity = 'info') => setSnack({ message, severity }), []); const logout = useCallback(() => { localStorage.removeItem('wc_token'); localStorage.removeItem('wc_user'); setToken(''); setUser(null); setHosts([]); setProcessesByHost({}); }, []); const api = useApi(token, logout);
  const toggleTheme = () => { const next = themeMode === 'dark' ? 'light' : 'dark'; localStorage.setItem('wc_theme', next); setThemeMode(next); };
  const setPage = useCallback(next => { const allowed = pageMeta[next] && (next !== 'admin' || user?.role === 'super_admin'); const pageId = allowed ? next : 'fleet'; location.hash = pageId; setPageState(pageId); }, [user?.role]);
  const theme = useMemo(() => {
    const dark = themeMode === 'dark';
    return createTheme({
      palette: {
        mode: themeMode,
        primary: { main: '#5e72e4', lighter: '#e8eafc', darker: '#344767' },
        secondary: { main: '#e91e63', lighter: '#fde3ed' },
        info: { main: '#17c1e8', lighter: '#d8f5fc' },
        success: { main: '#2dce89', lighter: '#d9f8e9' },
        warning: { main: '#fb8c00', lighter: '#fff0d8' },
        error: { main: '#f5365c', lighter: '#ffe0e7' },
        text: { primary: dark ? '#f8f9fa' : '#344767', secondary: dark ? '#b9c4d7' : '#67748e' },
        divider: dark ? 'rgba(255,255,255,.12)' : 'rgba(52,71,103,.12)',
        background: { default: dark ? '#161b2d' : '#f8f9fa', paper: dark ? '#202940' : '#ffffff', neutral: dark ? '#27314d' : '#eef2f7' }
      },
      shape: { borderRadius: 12 },
      typography: {
        fontFamily: 'Roboto, "Segoe UI", Arial, sans-serif',
        h2: { fontWeight: 700, letterSpacing: '-.025em' }, h3: { fontWeight: 700, letterSpacing: '-.025em' },
        h4: { fontWeight: 700, letterSpacing: '-.018em' }, h5: { fontWeight: 700 }, h6: { fontWeight: 700 },
        button: { textTransform: 'none', fontWeight: 700, letterSpacing: '.01em' }
      },
      components: {
        MuiCard: { styleOverrides: { root: { border: 0, borderRadius: 12, boxShadow: dark ? '0 10px 22px rgba(0,0,0,.22)' : '0 5px 16px rgba(31,38,59,.08)' } } },
        MuiPaper: { styleOverrides: { rounded: { borderRadius: 12 } } },
        MuiAppBar: { styleOverrides: { root: { boxShadow: 'none' } } },
        MuiButton: { styleOverrides: { root: { minHeight: 38, borderRadius: 9 }, containedPrimary: { color: '#fff', backgroundImage: 'linear-gradient(195deg, #5e72e4, #825ee4)', boxShadow: '0 5px 12px rgba(94,114,228,.25)', '&:hover': { backgroundImage: 'linear-gradient(195deg, #5063d0, #704bd1)', boxShadow: '0 7px 16px rgba(94,114,228,.32)' } } } },
        MuiTextField: { defaultProps: { variant: 'outlined' } },
        MuiChip: { styleOverrides: { root: { borderRadius: 7, fontWeight: 700 } } },
        MuiTableCell: { styleOverrides: { head: { color: dark ? '#c7d1e1' : '#67748e', fontWeight: 700, backgroundColor: dark ? 'rgba(255,255,255,.025)' : '#f8f9fa' } } }
      }
    });
  }, [themeMode]);
  useEffect(() => { document.documentElement.lang = lang; document.title = t('app.title'); }, [lang, t]);
  useEffect(() => { api('/api/setup/status').then(result => setSetupRequired(result.required)).catch(() => setSetupRequired(false)); }, [api]);
  const loadHosts = useCallback(async () => { if (!token) return; try { const next = await api('/api/v1/hosts'); setHosts(next); setSelectedId(current => { const id = next.some(host => host.id === current) ? current : next[0]?.id || null; const url = new URL(location.href); if (id) url.searchParams.set('host', id); else url.searchParams.delete('host'); history.replaceState({}, '', `${url.pathname}${url.search}${url.hash}`); return id; }); } catch (error) { notify(t(`error.${error.message}`), 'error'); } }, [token, api, notify, t]);
  useEffect(() => { loadHosts(); }, [loadHosts]);
  useEffect(() => { if (!token) return undefined; let timer; const protocol = location.protocol === 'https:' ? 'wss:' : 'ws:'; const socket = new WebSocket(`${protocol}//${location.host}/ws/ui?token=${encodeURIComponent(token)}`); socket.onopen = () => { setSocketState('live'); socket.send(JSON.stringify({ type: 'ui.subscribe', payload: { agentId: selectedId } })); }; socket.onmessage = event => { const message = JSON.parse(event.data); if (message.type === 'ui.telemetry') setHosts(current => current.map(host => host.id === message.agentId ? { ...host, telemetry: message.payload, online: true, lastSeen: message.sentAt } : host)); else if (message.type === 'ui.processes') setProcessesByHost(current => ({ ...current, [message.agentId]: message.payload?.processes || [] })); else if (message.type === 'ui.host.status' || message.type === 'ui.agent.pending') loadHosts(); else if (message.type === 'ui.access.changed') { setUser(current => ({ ...current, role: message.payload.role })); loadHosts(); } else if (message.type === 'ui.event') { const eventType = message.payload?.eventType || message.payload?.type; const eventLabel = eventType ? t(`event.${eventType}`) : t('error.generic'); notify(eventLabel === `event.${eventType}` ? eventType : eventLabel, message.payload?.severity || 'info'); } else if (message.type === 'ui.command') { const status = message.payload?.status; if (status === 'failed') notify(t(`error.${message.payload.error || 'generic'}`), 'error'); else if (status === 'succeeded') notify(t('command.completed'), 'success'); else if (status === 'expired') notify(t('command.expired'), 'warning'); } }; socket.onclose = () => { setSocketState('reconnecting'); timer = setTimeout(() => loadHosts(), 2500); }; return () => { clearTimeout(timer); socket.close(); }; }, [token, selectedId, loadHosts, notify, t]);
  useEffect(() => { const handler = () => setPage(location.hash.slice(1) || 'fleet'); window.addEventListener('hashchange', handler); return () => window.removeEventListener('hashchange', handler); }, [setPage]);
  const selectHost = (id, destination) => { setSelectedId(id); const url = new URL(location.href); url.searchParams.set('host', id); history.replaceState({}, '', `${url.pathname}${url.search}${url.hash}`); if (destination) setPage(destination); };
  const onSignedIn = result => { if (!result) { setSetupRequired(false); return; } const nextUser = { username: result.username, role: result.role, mustChangePassword: result.mustChangePassword }; localStorage.setItem('wc_token', result.token); localStorage.setItem('wc_user', JSON.stringify(nextUser)); setToken(result.token); setUser(nextUser); };
  const completePasswordChange = () => { setUser(current => { const next = { ...current, mustChangePassword: false }; localStorage.setItem('wc_user', JSON.stringify(next)); return next; }); notify(t('password.updated'), 'success'); };
  if (setupRequired === null) return <ThemeProvider theme={theme}><CssBaseline /><Box sx={{ minHeight: '100vh', display: 'grid', placeItems: 'center' }}><CircularProgressFallback /></Box></ThemeProvider>;
  if (setupRequired || !token || !user) return <ThemeProvider theme={theme}><CssBaseline /><AuthView setup={setupRequired} api={api} t={t} onSignedIn={onSignedIn} /></ThemeProvider>;
  const selected = hosts.find(host => host.id === selectedId) || null; const isSuper = user.role === 'super_admin'; const canManage = isSuper || user.role === 'admin'; const content = page === 'fleet' ? <FleetPage hosts={hosts} t={t} lang={lang} selectHost={selectHost} openAdmin={isSuper ? () => setPage('admin') : null} /> : page === 'dashboard' ? <DashboardPage host={selected} api={api} t={t} lang={lang} notify={notify} /> : page === 'processes' ? <ProcessesPage host={selected} processes={processesByHost[selected?.id] || []} onProcessesLoaded={(hostId, processes) => setProcessesByHost(current => ({ ...current, [hostId]: processes }))} api={api} canManage={canManage} t={t} notify={notify} /> : page === 'watchdog' ? <WatchdogPage host={selected} api={api} canManage={canManage} t={t} notify={notify} /> : page === 'activity' ? <ActivityPage host={selected} api={api} t={t} lang={lang} notify={notify} /> : <AdminPage hosts={hosts} api={api} t={t} lang={lang} notify={notify} selectHost={selectHost} />;
  const drawer = <Navigation page={page} setPage={setPage} isSuper={isSuper} t={t} onClose={() => setMobileOpen(false)} lang={lang} setLang={setLang} themeMode={themeMode} onToggleTheme={toggleTheme} onLogout={logout} />;
  const hostSelector = <FormControl size="small" fullWidth><InputLabel>{t('host.selector')}</InputLabel><Select label={t('host.selector')} value={selectedId || ''} onChange={event => selectHost(event.target.value)} disabled={!hosts.length}>{hosts.map(host => <MenuItem key={host.id} value={host.id}>{host.displayName}{host.online ? '' : ` (${t('common.offline')})`}</MenuItem>)}</Select></FormControl>;
  return <ThemeProvider theme={theme}><CssBaseline /><Box sx={{ display: 'flex', minHeight: '100vh', bgcolor: 'background.default' }}><Drawer variant={isMobile ? 'temporary' : 'permanent'} open={isMobile ? mobileOpen : true} onClose={() => setMobileOpen(false)} ModalProps={{ keepMounted: true }} sx={{ '& .MuiDrawer-paper': { width: DRAWER_WIDTH, boxSizing: 'border-box', border: 0, bgcolor: 'background.default' } }}>{drawer}</Drawer><Box component="main" sx={{ flexGrow: 1, minWidth: 0 }}><AppBar position="sticky" color="transparent" sx={{ bgcolor: themeMode === 'dark' ? 'rgba(22,27,45,.88)' : 'rgba(248,249,250,.86)', backdropFilter: 'blur(14px)' }}><Toolbar sx={{ minHeight: { xs: 64, sm: 72 }, px: { xs: 1.5, sm: 3, lg: 4 }, gap: { xs: .5, sm: 1.25 } }}><IconButton aria-label="Open navigation" onClick={() => setMobileOpen(true)} sx={{ display: { xs: 'inline-flex', md: 'none' }, flexShrink: 0 }}><MenuRounded /></IconButton><Box sx={{ minWidth: 0, flex: 1 }}><Typography variant="caption" color="text.secondary" sx={{ display: { xs: 'none', lg: 'block' }, fontWeight: 700, letterSpacing: .8, textTransform: 'uppercase' }}>{t(pageMeta[page]?.[1] || 'page.fleet.kicker')}</Typography><Typography variant="h6" noWrap>{t(pageMeta[page]?.[0] || 'page.fleet.title')}</Typography></Box><Chip size="small" color={socketState === 'live' ? 'success' : 'default'} label={t(`socket.${socketState === 'live' ? 'live' : socketState}`)} sx={{ display: { xs: 'none', lg: 'inline-flex' }, flexShrink: 0 }} /><Box sx={{ display: { xs: 'none', lg: 'block' }, width: 220, flexShrink: 0 }}>{hostSelector}</Box><Tooltip title={t('common.refresh')}><IconButton aria-label={t('common.refresh')} onClick={loadHosts} sx={{ flexShrink: 0 }}><RefreshRounded /></IconButton></Tooltip><Box sx={{ display: { xs: 'none', lg: 'contents' } }}><Tooltip title={themeMode === 'dark' ? t('theme.switchToLight') : t('theme.switchToDark')}><IconButton aria-label={themeMode === 'dark' ? t('theme.switchToLight') : t('theme.switchToDark')} onClick={toggleTheme}><>{themeMode === 'dark' ? <Brightness7Rounded /> : <Brightness4Rounded />}</></IconButton></Tooltip><Select aria-label="Language" size="small" value={lang} onChange={event => setLang(event.target.value)} sx={{ minWidth: 100, borderRadius: 1.75 }}><MenuItem value="vi">Tiếng Việt</MenuItem><MenuItem value="en">English</MenuItem></Select><Tooltip title={t('session.signOut')}><IconButton aria-label={t('session.signOut')} color="error" onClick={logout}><LogoutRounded /></IconButton></Tooltip></Box></Toolbar><Box sx={{ display: { xs: 'block', lg: 'none' }, px: { xs: 1.5, sm: 2 }, pb: 1.5 }}><Stack direction={{ xs: 'column', sm: 'row' }} spacing={1.25} alignItems={{ sm: 'center' }}><Box sx={{ flex: 1, minWidth: 0 }}>{hostSelector}</Box><Chip size="small" color={socketState === 'live' ? 'success' : 'default'} label={t(`socket.${socketState === 'live' ? 'live' : socketState}`)} sx={{ alignSelf: { xs: 'flex-start', sm: 'auto' }, flexShrink: 0 }} /></Stack></Box></AppBar><Box sx={{ width: '100%', p: { xs: 1.5, sm: 3, lg: 4 }, maxWidth: 1560, mx: 'auto' }}>{content}</Box></Box><Snackbar open={Boolean(snack)} autoHideDuration={4500} onClose={() => setSnack(null)} anchorOrigin={{ vertical: 'bottom', horizontal: isMobile ? 'center' : 'right' }}><Alert onClose={() => setSnack(null)} severity={snack?.severity || 'info'} variant="filled" sx={{ maxWidth: { xs: 'calc(100vw - 32px)', sm: 560 } }}>{snack?.message}</Alert></Snackbar>{user.mustChangePassword && <PasswordChangeDialog username={user.username} api={api} t={t} onComplete={completePasswordChange} />}</Box></ThemeProvider>;
}

function CircularProgressFallback() { return <Box sx={{ width: 40, height: 40, border: '4px solid', borderColor: 'primary.lighter', borderTopColor: 'primary.main', borderRadius: '50%', animation: 'spin 1s linear infinite', '@keyframes spin': { to: { transform: 'rotate(360deg)' } } }} />; }

export default App;